import { describe, expect, test } from "bun:test";
import detail from "../server/moves/fixtures/move-detail.json" with { type: "json" };
import response from "../server/moves/fixtures/moves-response.json" with { type: "json" };
import { AttributionSchema, MoveDetailSchema, MovesResponseSchema, MoveWindowSchema, WINDOW_HOURS } from "./moves.js";

// Parse-only checks of the moves contract against service output (fixtures generated by createMovesService on the
// synthetic series in src/server/moves/fixtures/series.ts, with a scanner, a crawler position and one news event).

describe("moves contract", () => {
  test("a universe response round-trips", () => {
    const r = MovesResponseSchema.parse(response);
    expect(MovesResponseSchema.parse(JSON.parse(JSON.stringify(r)))).toEqual(r);
    expect(r.rows.length).toBe(r.universe.coins);
    for (const row of r.rows) {
      const a = row.attribution;
      if (!a) continue;
      expect(Math.abs(a.btcPct + a.ethPct + (a.sectorPct ?? 0) + a.residualPct - a.totalPct)).toBeLessThan(1e-9);
    }
  });

  test("a detail response round-trips, with series, headlines and a null record", () => {
    const d = MoveDetailSchema.parse(detail);
    expect(MoveDetailSchema.parse(JSON.parse(JSON.stringify(d)))).toEqual(d);
    expect(d.series.length).toBe(d.attribution!.hours);
    expect(d.headlines.length).toBeGreaterThan(0);
    expect(d.record).toBeNull();
  });

  test("rejects a bad window, a non-finite number and a negative count", () => {
    expect(MoveWindowSchema.safeParse("1h").success).toBe(false);
    expect(Object.keys(WINDOW_HOURS)).toEqual(["4h", "24h", "72h"]);
    const a = MoveDetailSchema.parse(detail).attribution!;
    expect(AttributionSchema.safeParse({ ...a, residualZ: Number.NaN }).success).toBe(false);
    expect(AttributionSchema.safeParse({ ...a, hours: -1 }).success).toBe(false);
    expect(MovesResponseSchema.safeParse({ ...response, state: "partial" }).success).toBe(false);
  });
});
